def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    last_my = my[-1]
    last_op = op[-1]

    opp_def = sum(1 for a in op if a == 'D')
    my_def = sum(1 for a in my if a == 'D')

    if opp_def == 0:
        if my_def >= 1:
            return 'D'
        if n >= 12 and rng.random() < 0.3:
            return 'D'
        return 'C'

    streakD = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            streakD += 1
        else:
            break

    w = 10 if n >= 10 else n
    recent_def = 0
    for i in range(n - w, n):
        if op[i] == 'D':
            recent_def += 1
    recent_coop = w - recent_def

    follow = 0
    total = 0
    start = 1 if n < 9 else n - 8
    for i in range(start, n):
        if op[i] == my[i - 1]:
            follow += 1
        total += 1
    follower = (follow / total) if total > 0 else 1.0

    if last_op == 'D':
        if recent_def == w:
            return 'D'

        if streakD >= 3:
            opp_c = n - opp_def
            win = streakD + 6
            if win > n:
                win = n
            coop_near = 0
            for i in range(n - win, n):
                if op[i] == 'C':
                    coop_near += 1
            if coop_near >= 2 and opp_c * 2 >= opp_def and streakD <= 5:
                if last_my == 'D':
                    return 'C'
                if n >= 2 and last_my == 'C' and my[-2] == 'D':
                    return 'C'
            return 'D'

        if streakD == 1:
            opp_c = n - opp_def
            if last_my == 'C' and opp_c * 4 >= n * 3 and follower >= 0.65:
                return 'C' if rng.random() < 0.4 else 'D'
            if last_my == 'D':
                return 'C' if rng.random() < 0.6 else 'D'
            return 'D' if rng.random() < 0.85 else 'C'

        if last_my == 'C':
            return 'D' if rng.random() < 0.8 else 'C'
        return 'D' if rng.random() < 0.55 else 'C'

    if n >= 5 and op[-5:] == ['D', 'D', 'C', 'C', 'C']:
        return 'D' if rng.random() < 0.8 else 'C'

    opp_c = n - opp_def

    my_score = 0
    opp_score = 0
    for a, b in history:
        if a == 'C':
            if b == 'C':
                my_score += 3
                opp_score += 3
            else:
                opp_score += 5
        else:
            if b == 'C':
                my_score += 5
            else:
                my_score += 1
                opp_score += 1

    not_punish = 0
    for i in range(n - 1):
        if my[i] == 'D' and op[i + 1] == 'C':
            not_punish += 1

    if recent_def <= 1 and opp_c * 5 >= n * 4:
        if not_punish >= 2 and rng.random() < 0.9:
            return 'D'
        if n >= 40 and rng.random() < 0.03:
            return 'D'

    if recent_def >= 6:
        return 'D' if rng.random() < 0.75 else 'C'

    if opp_def > opp_c:
        return 'D' if rng.random() < 0.65 else 'C'

    if my_score + 3 < opp_score and recent_def >= 2:
        return 'D' if rng.random() < 0.3 else 'C'

    if recent_def <= 3:
        return 'C' if rng.random() < 0.97 else 'D'

    return 'C' if rng.random() < 0.85 else 'D'
